import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this would verify JWT signature
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
  req.tenantId = payload.tenant_id;
  req.userId = payload.sub;
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/reports', extractTenant, async (req, res) => {
  try {
    const { status, date_from, date_to, sort_by, order } = req.query;

    let query = `SELECT id, title, created_at, status, author_id 
                 FROM reports WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (status) {
      query += ` AND status = $${paramIdx++}`;
      params.push(status);
    }
    if (date_from) {
      query += ` AND created_at >= $${paramIdx++}`;
      params.push(date_from);
    }
    if (date_to) {
      query += ` AND created_at <= $${paramIdx++}`;
      params.push(date_to);
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'status'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder}`;

    // Pagination
    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    const offset = parseInt(req.query.offset) || 0;
    query += ` LIMIT ${limit} OFFSET ${offset}`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  try {
    const { ids, format } = req.body;
    if (!Array.isArray(ids) || ids.length === 0) {
      return res.status(400).json({ error: 'ids required' });
    }

    // Build IN clause dynamically for variable-length array
    const placeholders = ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `SELECT * FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`;
    const result = await pool.query(query, [req.tenantId, ...ids]);

    if (format === 'csv') {
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      return res.send(csv);
    }
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin analytics - the vulnerable endpoint
app.get('/api/v2/analytics/custom', extractTenant, async (req, res) => {
  try {
    const { metric, group_by, having_clause } = req.query;

    const allowedMetrics = ['count(*)', 'count(distinct author_id)', 'avg(score)'];
    const allowedGroups = ['status', 'DATE_TRUNC(\'month\', created_at)', 'author_id'];

    const selectedMetric = allowedMetrics.includes(metric) ? metric : 'count(*)';
    const selectedGroup = allowedGroups.includes(group_by) ? group_by : 'status';

    let query = `SELECT ${selectedGroup} as dimension, ${selectedMetric} as value 
                 FROM reports WHERE tenant_id = $1 
                 GROUP BY ${selectedGroup}`;

    // HAVING clause for filtering aggregates
    if (having_clause) {
      query += ` HAVING ${having_clause}`;
    }

    query += ` ORDER BY value DESC LIMIT 100`;

    const result = await pool.query(query, [req.tenantId]);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Analytics error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Report service listening on :3000'));
